//! Optional Steam launch entries use the existing uninstall-registry scan.
//! No library files, SDK, network, watcher or per-file index metadata is needed.

use crate::core::{Item, Kind};

/// Recognize only the canonical URI generated by this provider. Do not pass
/// arbitrary Steam commands, arguments or malformed identifiers to icon lookup.
pub(crate) fn app_id(target: &str) -> Option<u32> {
    let value = target.strip_prefix("steam://run/")?;
    if value.starts_with('0') || !value.bytes().all(|byte| byte.is_ascii_digit()) {
        return None;
    }
    value.parse::<u32>().ok().filter(|id| *id != 0)
}

/// Parse the already-enumerated UTF-16 registry key without allocating a name.
fn registry_app_id(name: &[u16]) -> Option<u32> {
    const PREFIX: &[u8] = b"Steam App ";
    if name.len() <= PREFIX.len()
        || !name
            .iter()
            .zip(PREFIX)
            .all(|(unit, byte)| *unit == u16::from(*byte))
    {
        return None;
    }
    let digits = &name[PREFIX.len()..];
    if digits[0] == u16::from(b'0') {
        return None;
    }
    let mut id = 0u32;
    for &unit in digits {
        let digit = unit.checked_sub(u16::from(b'0'))?;
        if digit > 9 {
            return None;
        }
        id = id.checked_mul(10)?.checked_add(u32::from(digit))?;
    }
    Some(id)
}

/// Disabled providers return before parsing keys, copying titles or allocating
/// Item search caches. Existing presence/removal snapshots remain independent.
pub(crate) fn append_game(enabled: bool, key: &[u16], title: &str, games: &mut Vec<Item>) {
    if !enabled {
        return;
    }
    let Some(app_id) = registry_app_id(key) else {
        return;
    };
    if title.is_empty() || title.chars().any(char::is_control) {
        return;
    }
    let id = format!("steam:{app_id}");
    // Four registry views may expose the same AppID. Game lists are small, so
    // reuse the output vector rather than retaining another lookup allocation.
    if games.iter().any(|game| game.id == id) {
        return;
    }
    games.push(Item::new(
        id,
        title,
        crate::i18n::tr("Jeu Steam"),
        "\u{E7FC}",
        Kind::Application,
        format!("steam://run/{app_id}"),
    ));
}

/// Read artwork only on the existing icon worker, when a visible row requests
/// it. The URI remains the cache identity; no icon map is added to every Item.
pub(crate) fn icon_source(app_id: u32) -> Option<String> {
    use windows_sys::Win32::Foundation::ERROR_SUCCESS;
    use windows_sys::Win32::System::Registry::{
        RegCloseKey, RegOpenKeyExW, RegQueryValueExW, HKEY_CURRENT_USER, HKEY_LOCAL_MACHINE,
        KEY_READ, KEY_WOW64_32KEY, KEY_WOW64_64KEY, REG_SZ,
    };
    let key_name: Vec<u16> =
        format!("SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\Steam App {app_id}")
            .encode_utf16()
            .chain(Some(0))
            .collect();
    let value_name: Vec<u16> = "DisplayIcon".encode_utf16().chain(Some(0)).collect();
    for root in [HKEY_CURRENT_USER, HKEY_LOCAL_MACHINE] {
        for view in [KEY_WOW64_64KEY, KEY_WOW64_32KEY] {
            let mut key = std::ptr::null_mut();
            // SAFETY: all pointers reference live, terminated names or bounded
            // writable buffers during synchronous read-only registry calls.
            if unsafe { RegOpenKeyExW(root, key_name.as_ptr(), 0, KEY_READ | view, &mut key) }
                != ERROR_SUCCESS
            {
                continue;
            }
            let mut buffer = [0u16; 2048];
            let mut length = std::mem::size_of_val(&buffer) as u32;
            let mut kind = 0;
            let result = unsafe {
                RegQueryValueExW(
                    key,
                    value_name.as_ptr(),
                    std::ptr::null(),
                    &mut kind,
                    buffer.as_mut_ptr().cast(),
                    &mut length,
                )
            };
            unsafe { RegCloseKey(key) };
            if result != ERROR_SUCCESS
                || kind != REG_SZ
                || !length.is_multiple_of(2)
                || length as usize > std::mem::size_of_val(&buffer)
            {
                continue;
            }
            let buffer = &buffer[..length as usize / 2];
            let end = buffer
                .iter()
                .position(|unit| *unit == 0)
                .unwrap_or(buffer.len());
            let value = String::from_utf16_lossy(&buffer[..end]);
            if let Some(path) = icon_path(&value) {
                return Some(path);
            }
        }
    }
    None
}

fn icon_path(value: &str) -> Option<String> {
    let path = crate::uninstall_inventory::parse_display_icon(value)?;
    // A Steam registry value can be edited by its user. Reject remote/device
    // paths and require existing local artwork before asking Shell to read it.
    path.is_file().then(|| path.to_string_lossy().into_owned())
}

#[cfg(test)]
mod tests {
    use super::*;

    fn key(value: &str) -> Vec<u16> {
        value.encode_utf16().collect()
    }

    #[test]
    fn registry_and_launch_ids_are_bounded_and_canonical() {
        for id in ["1", "2224640", "4294967295"] {
            let expected = id.parse::<u32>().unwrap();
            assert_eq!(
                registry_app_id(&key(&format!("Steam App {id}"))),
                Some(expected)
            );
            assert_eq!(app_id(&format!("steam://run/{id}")), Some(expected));
        }
        for id in [
            "",
            "0",
            "01",
            "-1",
            "+1",
            " 1",
            "1 ",
            "4294967296",
            "1/2",
            "1?x",
            "1\0",
        ] {
            assert!(
                registry_app_id(&key(&format!("Steam App {id}"))).is_none(),
                "{id:?}"
            );
            assert!(app_id(&format!("steam://run/{id}")).is_none(), "{id:?}");
        }
        assert!(registry_app_id(&key("steam app 1")).is_none());
        assert!(app_id("steam://uninstall/1").is_none());
        assert!(app_id("steam://run/١").is_none());
    }

    #[test]
    fn disabled_provider_builds_no_game_entries_or_output_allocation() {
        let mut games = Vec::new();
        append_game(false, &key("Steam App 2224640"), "Artisan TD", &mut games);
        assert!(games.is_empty());
        assert_eq!(games.capacity(), 0);
    }

    #[test]
    fn games_keep_unicode_names_and_deduplicate_by_appid_across_views() {
        let mut games = Vec::new();
        let steam_key = key("Steam App 2224640");
        append_game(true, &steam_key, "Étoiles — Ελληνικά 🎮", &mut games);
        append_game(true, &steam_key, "Another registry view", &mut games);
        append_game(
            true,
            &key("Steam App 2"),
            "Étoiles — Ελληνικά 🎮",
            &mut games,
        );
        assert_eq!(games.len(), 2);
        assert_eq!(games[0].id, "steam:2224640");
        assert_eq!(games[0].title, "Étoiles — Ελληνικά 🎮");
        assert_eq!(games[0].kind, Kind::Application);
        assert_eq!(games[0].target, "steam://run/2224640");
        assert!(games[0].arguments.is_empty());
        append_game(true, &key("Steam App 3"), "", &mut games);
        append_game(true, &key("Steam App 4"), "Bad\nName", &mut games);
        append_game(true, &key("Unrelated software"), "App", &mut games);
        assert_eq!(games.len(), 2);
    }

    #[test]
    fn artwork_metadata_accepts_local_existing_icons_and_rejects_commands() {
        let root = std::env::temp_dir().join(format!("SuperMenu-SteamIcon-{}", std::process::id()));
        std::fs::create_dir_all(&root).unwrap();
        let icon = root.join("accentué, icon.ico");
        std::fs::write(&icon, []).unwrap();
        let path = icon.to_string_lossy();
        assert_eq!(
            icon_path(&format!("\"{path}\", 0")).as_deref(),
            Some(path.as_ref())
        );
        assert_eq!(icon_path(&path).as_deref(), Some(path.as_ref()));
        for value in [
            format!("\"{path}\" --arguments"),
            r"\\server\share\icon.ico".into(),
            r"\\?\C:\icon.ico".into(),
            r"C:\absent\steam-icon.ico".into(),
            "steam://run/2224640".into(),
            "relative.ico".into(),
        ] {
            assert!(icon_path(&value).is_none(), "{value}");
        }
        std::fs::remove_dir_all(root).unwrap();
    }
}
